#!/usr/bin/env bash
set -Eeuo pipefail
TARGET="/usr/share/dvswitch/index.php"
BASE="/etc/dvswitch-mode-buttons"
BACKUP="/var/backups/dvswitch-mode-buttons/install-$(date +%Y%m%d-%H%M%S)"
[[ $EUID -eq 0 ]] || { echo "ERROR: run with sudo" >&2; exit 1; }
[[ $# -eq 1 && ( "$1" == --check || "$1" == --install ) ]] || { echo "Usage: sudo $0 --check|--install" >&2; exit 2; }
[[ -f "$TARGET" && -x /opt/MMDVM_Bridge/dvswitch.sh ]] || { echo "ERROR: DVSwitch dashboard or mode command is missing" >&2; exit 1; }
if [[ "$1" == --check ]]; then
  echo "DVSwitch Mode Buttons single-file installer"
  echo "Dashboard: $TARGET"
  echo "MMDVM_Bridge mode command: /opt/MMDVM_Bridge/dvswitch.sh"
  [[ -f /var/lib/dvswitch/dvs/var.txt ]] && echo "DVSwitch var.txt: found" || echo "DVSwitch var.txt: not found"
  echo "PASS: prerequisites checked; no files changed"
  exit 0
fi
install -d -m 700 -o root -g root "$BACKUP" "$BASE"
[[ -e "$TARGET" ]] && cp -a "$TARGET" "$BACKUP/index.php"
for p in /usr/local/sbin/dvswitch-mode-buttons /usr/local/sbin/dvswitch-dmr-network /usr/share/dvswitch/dvswitch-mode-buttons.php /etc/sudoers.d/dvswitch-mode-buttons; do [[ -e "$p" ]] && cp -a "$p" "$BACKUP/$(basename "$p")"; done
write_payload(){ echo "$2" | base64 -d > "$1"; }
write_payload /tmp/dmb-network.b64 ''
write_payload /tmp/dmb-mode.b64 ''
write_payload /tmp/dmb-endpoint.b64 ''
write_payload /tmp/dmb-preset.b64 ''
write_payload /tmp/dmb-sudoers.b64 ''
install -o root -g root -m 755 /tmp/dmb-mode.b64 /usr/local/sbin/dvswitch-mode-buttons
install -o root -g root -m 755 /tmp/dmb-network.b64 /usr/local/sbin/dvswitch-dmr-network
install -o root -g root -m 755 /tmp/dmb-preset.b64 "$BASE/dvswitch-mode-buttons.sh"
install -o root -g root -m 644 /tmp/dmb-endpoint.b64 /usr/share/dvswitch/dvswitch-mode-buttons.php
install -o root -g root -m 440 /tmp/dmb-sudoers.b64 /etc/sudoers.d/dvswitch-mode-buttons
rm -f /tmp/dmb-network.b64 /tmp/dmb-mode.b64 /tmp/dmb-endpoint.b64 /tmp/dmb-preset.b64 /tmp/dmb-sudoers.b64
visudo -cf /etc/sudoers.d/dvswitch-mode-buttons >/dev/null || { echo "ERROR: sudoers validation failed" >&2; exit 1; }
php -l /usr/share/dvswitch/dvswitch-mode-buttons.php >/dev/null || { echo "ERROR: PHP validation failed" >&2; exit 1; }
export TARGET
python3 - <<'PY'
import os, shutil
from pathlib import Path
p=Path(os.environ["TARGET"]); s=p.read_text()
marker="<!-- DVSwitch-Mode-Buttons single-file v1 -->"
if marker not in s:
    pos=s.rfind("</body>")
    if pos<0: raise SystemExit("ERROR: </body> not found")
    block='''<!-- DVSwitch-Mode-Buttons single-file v1 -->
<div id="dvs-mode-buttons" aria-label="Select Mode"><div class="dvs-mode-buttons-title">Select Mode</div>
<button type="button" class="button link" data-mode="BM">BM</button><button type="button" class="button link" data-mode="TGIF">TGIF</button><button type="button" class="button link" data-mode="STFU">STFU</button><button type="button" class="button link" data-mode="YSF">YSF</button><button type="button" class="button link" data-mode="P25">P25</button><button type="button" class="button link" data-mode="NXDN">NXDN</button><button type="button" class="button link" data-mode="DSTAR">D-Star</button></div>
<style>#dvs-mode-buttons{text-align:center;margin:4px auto 8px}#dvs-mode-buttons .dvs-mode-buttons-title{font-weight:bold;margin-bottom:2px}#dvs-mode-buttons button{min-width:72px;height:32px;padding:4px 10px}#dvs-mode-buttons button.selected{background-color:#008000}#dvs-mode-buttons button:disabled{opacity:.65}</style>
<script>(function(){const box=document.getElementById("dvs-mode-buttons"),buttons=[...box.querySelectorAll("button")];function select(b){buttons.forEach(x=>x.classList.toggle("selected",x===b))}buttons.forEach(b=>b.addEventListener("click",async()=>{buttons.forEach(x=>x.disabled=true);try{const r=await fetch("/dvswitch/dvswitch-mode-buttons.php?mode="+encodeURIComponent(b.dataset.mode)),j=await r.json();if(!j.ok)throw new Error(j.output||j.error||"switch failed");select(b)}catch(e){alert("Mode switch failed: "+e.message)}finally{buttons.forEach(x=>x.disabled=false)}}))})();</script>'''
    tmp=p.with_name(p.name+".tmp-mode-buttons"); tmp.write_text(s[:pos]+block+s[pos:]); shutil.copystat(p,tmp); st=os.stat(p); os.chown(tmp,st.st_uid,st.st_gid); os.replace(tmp,p)
PY
bash -n /usr/local/sbin/dvswitch-mode-buttons
bash -n /usr/local/sbin/dvswitch-dmr-network
echo "PASS: seven dashboard buttons and mode switching installed"
echo "PASS: no TG/ref persistence, Tx display, refresh state, or startup service installed"
echo "PASS: backup: $BACKUP"

